package com.shazwan.idash;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Rect;import android.view.*;import android.widget.*;
/** Runs against the actual UI on a disposable API27 emulator; no OEM fixtures. */
public class SmokeChecks extends Instrumentation {
 int count;LauncherActivity a;boolean layoutOnly;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);count++;}
 View find(View v,String description){if(description.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View f=find(g.getChildAt(i),description);if(f!=null)return f;}}return null;}
 int countDescription(View v,String description){int n=description.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())?1:0;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)n+=countDescription(g.getChildAt(i),description);}return n;}
 void tap(String description){runOnMainSync(()->{View v=find(a.stage,description);if(v==null)throw new AssertionError("Missing "+description);v.performClick();});waitForIdleSync();}
 public void onCreate(Bundle b){super.onCreate(b);layoutOnly=b!=null&&"true".equals(b.getString("layoutOnly"));start();}
 public void onStart(){Bundle r=new Bundle();try{
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();long end=SystemClock.elapsedRealtime()+20000;while(!a.loaded&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);waitForIdleSync();
  runOnMainSync(()->{check(a.loaded,"app discovery completes");check(find(a.stage,"Panel")!=null&&find(a.stage,"Customize")!=null&&find(a.stage,"Control Center")!=null,"three header actions exist");check(!a.panelVisible&&a.panelBox==null,"optional panel hidden on fresh launch");check(java.util.Arrays.equals(a.slots,new String[]{"Bluetooth","Files","YouTube"}),"three favorites in requested order");check(find(a.stage,"Favorite Maps")==null&&find(a.stage,"Favorite Music")==null&&find(a.stage,"Favorite Radio")==null,"removed favorites absent");check(a.apps.size()>0,"real installed activities discovered");
   try{check(a.getAssets().list("mrios/icons").length==36,"all36 portable icons present");check(MrIosTheme.wallpapers(a.getAssets()).length==24,"all24 wallpapers present");android.graphics.Bitmap wallpaper=MrIosTheme.decode(a.getAssets(),"mrios/wallpapers/47.jpg",1280);check(Math.max(wallpaper.getWidth(),wallpaper.getHeight())<=1280,"wallpaper decode bounded");}catch(java.io.IOException e){throw new AssertionError(e);}
   check(find(a.stage,"Power widget")==null,"power removed");
   check(countDescription(a.stage,"Favorite Bluetooth")==1&&countDescription(a.stage,"Favorite Files")==1&&countDescription(a.stage,"Favorite YouTube")==1,"shortcuts only in dock");check(a.clock.getText().length()>=4,"clock populated");check(find(a.stage,"Calendar widget")!=null,"calendar exists");check(find(a.stage,"JAKIM calendar widget")!=null,"JAKIM replaces power");Rect screen=new Rect(0,0,a.stage.getWidth(),a.stage.getHeight());for(String name:new String[]{"Clock widget","Favorite Files","Favorite Bluetooth","Apps","Settings"}){View v=find(a.stage,name);int[] xy=new int[2];v.getLocationOnScreen(xy);check(screen.contains(xy[0],xy[1],xy[0]+v.getWidth(),xy[1]+v.getHeight()),name+" fits screen");check(v.getHeight()>=a.dp(48),name+" touch target");}});
  java.util.Map<String,JakimCalendar.Day> days=JakimCalendar.load(getTargetContext(),"SGR02");
  check(days.size()==365,"official year cache parses");java.text.SimpleDateFormat prayerDate=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",java.util.Locale.US);prayerDate.setTimeZone(JakimCalendar.MY);check(JakimCalendar.nextPrayer(days,prayerDate.parse("2026-11-02 04:00").getTime()).startsWith("Subuh"),"next prayer before dawn");check(JakimCalendar.nextPrayer(days,prayerDate.parse("2026-11-02 06:00").getTime()).startsWith("Zohor"),"sunrise excluded from next prayer countdown");check(JakimCalendar.nextPrayer(days,prayerDate.parse("2026-11-02 23:00").getTime()).startsWith("Subuh"),"next prayer rolls to tomorrow cache");check(JakimCalendar.nextPrayer(days,prayerDate.parse("2027-01-01 23:00").getTime()).startsWith("Tiada"),"missing future timetable does not invent prayer time");check(days.get("2026-11-02")!=null,"official current date available");check(days.get("2027-11-02")==null,"expired year not reused");check(JakimCalendar.date("31-Dis-2026").equals("2026-12-31"),"Malay date parses");check(JakimCalendar.key(1793548800000L).equals("2026-11-02"),"Malaysia date boundary");
  runOnMainSync(()->a.setJakimZone("SGR02"));end=SystemClock.elapsedRealtime()+20000;while(a.jakimLoading&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);waitForIdleSync();runOnMainSync(()->{check(a.loadedZone.equals("SGR02"),"zone loaded off UI thread");check(a.jakimText.getText().toString().contains("JAKIM · SGR02"),"selected zone shown");a.prefs.edit().putBoolean("jakim",false).apply();a.render();check(find(a.stage,"JAKIM calendar widget")==null,"JAKIM visibility saved");a.prefs.edit().putBoolean("jakim",true).apply();a.render();check(find(a.stage,"JAKIM calendar widget")!=null,"JAKIM visibility restored");});
  waitForIdleSync();runOnMainSync(()->{View prayer=find(a.stage,"JAKIM calendar widget");Rect visible=new Rect();View clockCard=find(a.stage,"Clock widget");check(clockCard.getBottom()<=prayer.getTop(),"clock and prayer cards have disjoint bounds in same left stack");check(clockCard.getParent()==prayer.getParent(),"clock and prayer retain one left stack");prayer.getGlobalVisibleRect(visible);View dock=find(a.stage,"Favorite Files");check(dock.getHeight()>=a.dp(48)&&dock.getHeight()<=a.dp(60),"flattened dock retains accessible touch height");int[] dockAt=new int[2];dock.getLocationOnScreen(dockAt);check(visible.bottom<=dockAt[1],"prayer card above dock");check(a.jakimNext.getText().length()>0,"prayer countdown or unavailable status present");});
  tap("Apps");runOnMainSync(()->{check(a.page.equals("apps"),"dock opens library");check(a.grid.getChildCount()>0,"drawer populated");a.search.setText("zzzz_idash_missing_app");check(a.drawerCount.getText().toString().equals("0 apps"),"search filters actual list");check(a.grid.getChildCount()==1,"empty result message");a.search.setText("");check(a.grid.getChildCount()>0,"search clears");a.onBackPressed();check(a.page.equals("home"),"Back returns home");});
  runOnMainSync(()->{LauncherActivity.App chosen=a.apps.get(0);a.prefs.edit().remove("three_favorites").putString("slot5",chosen.component).remove("favorite_Bluetooth").apply();a.migrateFavorites();check(a.assigned(0)!=null&&a.assigned(0).component.equals(chosen.component),"old Bluetooth assignment migrated");a.assign(0,chosen);check(a.assigned(0).component.equals(chosen.component),"favorite assigned");String saved=a.prefs.getString("favorite_Bluetooth","");a.render();check(a.assigned(0).component.equals(saved),"favorite survives UI rebuild");a.prefs.edit().putBoolean("calendar",false).apply();a.render();check(find(a.stage,"Calendar widget")==null,"widget visibility saved");a.prefs.edit().putBoolean("calendar",true).apply();a.render();check(find(a.stage,"Calendar widget")!=null,"widget restored");});
  String expected=a.prefs.getString("favorite_Bluetooth","");runOnMainSync(()->a.finish());waitForIdleSync();a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));end=SystemClock.elapsedRealtime()+20000;while(!a.loaded&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);waitForIdleSync();runOnMainSync(()->check(a.assigned(0)!=null&&a.assigned(0).component.equals(expected),"favorite survives Activity restart"));
  if(!layoutOnly){tap("Control Center");
  end=SystemClock.elapsedRealtime()+15000;boolean volumeSeen=false;
  while(SystemClock.elapsedRealtime()<end){android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null&&!root.findAccessibilityNodeInfosByText("Media volume").isEmpty()){volumeSeen=true;break;}Thread.sleep(200);}
  check(volumeSeen,"Control Center exposes media volume");
  sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();
  runOnMainSync(()->a.openSettings(android.provider.Settings.ACTION_SETTINGS));end=SystemClock.elapsedRealtime()+15000;boolean settingsSeen=false;
  while(SystemClock.elapsedRealtime()<end){android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null&&"com.android.settings".contentEquals(root.getPackageName())){settingsSeen=true;break;}Thread.sleep(200);}
  check(settingsSeen,"actual Android Settings opens outside launcher");check(!a.resumed,"launcher pauses behind external app");
  getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);end=SystemClock.elapsedRealtime()+15000;while(!a.resumed&&SystemClock.elapsedRealtime()<end)Thread.sleep(200);check(a.resumed,"launcher resumes after external app Back");}
  r.putString("stream","PASS: "+count+" iDash API27 "+(layoutOnly?"layout/theme":"UI")+" assertions\n");finish(Activity.RESULT_OK,r);
 }catch(Throwable e){r.putString("stream","FAIL after "+count+": "+e+"\n");finish(Activity.RESULT_CANCELED,r);}finally{if(a!=null)runOnMainSync(()->a.finish());}}
}
